        // Alternate colors
        if ((row + col) % 2 === 0) {
            ctx.fillStyle = '#f8f9fa';
        } else {
            ctx.fillStyle = '#4a4e69';
        }

        ctx.fillRect(x, y, squareSize, squareSize);
    }
}

